/**
 * @name Jungle Glass
 * @author jack-o-vscode
 * @description Personal theme: custom background image, frosted glass panels, sea-blue accent, custom font.
 * @version 1.4.0
 */

/* =====================================================================
   DEFAULT SETTINGS
   To change these from inside Discord, paste settings.css into
   Vencord's QuickCSS (Settings > Vencord > Edit QuickCSS) and edit there.
   Values in QuickCSS override the ones below.
   ===================================================================== */
:root {
    /* Accent colour (buttons, links, toggles, highlights).
       Hover and light shades are worked out from it automatically. */
    --jg-accent: #0fa3b8;

    /* Ping colour (@mentions, and the highlight on messages that ping you) */
    --jg-mention: #f5c542;

    /* Font: "Nunito", "Inter", "Outfit", "Quicksand", "Courier New" or "gg sans" (Discord's default) */
    --jg-font: "Nunito";

    /* Frosted glass */
    --jg-blur: 12px;              /* blur behind panels (0px = no blur) */
    --jg-panel-opacity: 0.5;      /* panel darkness: 0 = see-through, 1 = solid */
    --jg-popup-opacity: 0.9;      /* menus, popouts and dialogs */
    --jg-tint: 8 16 20;           /* panel colour as R G B (default: very dark blue-black) */

    /* Background */
    --jg-bg-dim: 0.2;             /* darkens the whole image: 0 = none, 1 = black */
    --jg-bg-position: center;     /* which part of the image to keep when the window is resized */

    /* Animated effect: none, snow, rain, leaves, stars or fireflies (no quotes) */
    --jg-effect: none;
    --jg-effect-speed: 1;         /* 0.25 = slow, 3 = fast */
    --jg-effect-size: 1;          /* 0.5 = tiny, 2.5 = big */
    --jg-effect-opacity: 0.8;     /* 0.2 = faint, 1 = full */
    --jg-effect-layer: panels;    /* panels = under the text, front = over everything */
}

/* =====================================================================
   THEME - you normally don't need to touch anything below.
   ===================================================================== */

/* ---- Derived accent shades ---- */
:root {
    --jg-accent-hover: color-mix(in oklab, var(--jg-accent), black 18%);
    --jg-accent-light: color-mix(in oklab, var(--jg-accent), white 35%);
}

/* ---- Font ---- */
:root,
.theme-dark,
.theme-light,
.visual-refresh {
    --font-primary: var(--jg-font), "gg sans", "Segoe UI", sans-serif !important;
    --font-display: var(--jg-font), "gg sans", "Segoe UI", sans-serif !important;
    --font-headline: var(--jg-font), "gg sans", "Segoe UI", sans-serif !important;
}

/* ---- Accent colour ---- */
:root,
.theme-dark,
.theme-light,
.visual-refresh {
    --brand-500: var(--jg-accent) !important;
    --brand-experiment: var(--jg-accent) !important;
    --brand-experiment-500: var(--jg-accent) !important;
    --brand-560: var(--jg-accent-hover) !important;
    --brand-600: var(--jg-accent-hover) !important;
    --brand-experiment-560: var(--jg-accent-hover) !important;
    --brand-experiment-600: var(--jg-accent-hover) !important;
    --brand-360: var(--jg-accent-light) !important;
    --brand-400: var(--jg-accent-light) !important;
    --bg-brand: var(--jg-accent) !important;
    --text-brand: var(--jg-accent-light) !important;
    --text-link: var(--jg-accent-light) !important;
    --control-brand-foreground: var(--jg-accent-light) !important;
    --control-brand-foreground-new: var(--jg-accent-light) !important;
    --button-filled-brand-background: var(--jg-accent) !important;
    --button-filled-brand-background-hover: var(--jg-accent-hover) !important;
    --button-filled-brand-background-active: var(--jg-accent-hover) !important;
    --control-primary-background-default: var(--jg-accent) !important;
    --control-primary-background-hover: var(--jg-accent-hover) !important;
    --control-primary-background-active: var(--jg-accent-hover) !important;
    --redesign-button-primary-background: var(--jg-accent) !important;
    --redesign-button-primary-hover-background: var(--jg-accent-hover) !important;
    --redesign-button-primary-pressed-background: var(--jg-accent-hover) !important;
    --mention-foreground: var(--jg-mention) !important;
    --mention-background: color-mix(in srgb, var(--jg-mention) 22%, transparent) !important;
    --background-mentioned: color-mix(in srgb, var(--jg-mention) 10%, transparent) !important;
    --background-mentioned-hover: color-mix(in srgb, var(--jg-mention) 14%, transparent) !important;
    --focus-primary: var(--jg-accent) !important;
}

/* ---- Ping colour on hover (Discord uses the accent by default) ---- */
.mention.interactive:hover {
    background-color: var(--jg-mention) !important;
    color: #1a1a1a !important;
}

/* ---- Make Discord's own backgrounds see-through ---- */
.theme-dark,
.theme-light,
.visual-refresh {
    --background-base-lowest: transparent !important;
    --background-base-lower: transparent !important;
    --background-base-low: transparent !important;
    --background-primary: transparent !important;
    --background-secondary: transparent !important;
    --background-secondary-alt: transparent !important;
    --background-tertiary: transparent !important;
    --bg-base-primary: transparent !important;
    --bg-base-secondary: transparent !important;
    --bg-base-tertiary: transparent !important;
    --chat-background-default: transparent !important;
    --home-background: transparent !important;

    /* Menus, popouts and dialogs stay mostly solid so text is readable */
    --background-floating: rgb(var(--jg-tint) / var(--jg-popup-opacity)) !important;
    --background-nested-floating: rgb(var(--jg-tint) / var(--jg-popup-opacity)) !important;
    --background-surface-high: rgb(var(--jg-tint) / var(--jg-popup-opacity)) !important;
    --background-surface-higher: rgb(var(--jg-tint) / var(--jg-popup-opacity)) !important;
    --background-surface-highest: rgb(var(--jg-tint) / var(--jg-popup-opacity)) !important;
    --modal-background: rgb(var(--jg-tint) / var(--jg-popup-opacity)) !important;
    --modal-footer-background: rgb(0 0 0 / 0.25) !important;

    /* Message box */
    --channeltextarea-background: rgb(0 0 0 / 0.35) !important;
    --input-background: rgb(0 0 0 / 0.35) !important;
}

/* ---- The background image ---- */
html,
body {
    background: #000 !important;
}

#app-mount {
    background:
        linear-gradient(rgb(0 0 0 / var(--jg-bg-dim)), rgb(0 0 0 / var(--jg-bg-dim))),
        var(--jg-image) var(--jg-bg-position) / cover no-repeat !important;
}

/* ---- Frosted glass panels ---- */
/* Left side: server list + channel list + your user panel */
[class^="sidebar_"],
/* Right side: chat, friends list, member list, etc. */
[class^="page_"],
/* Settings screens */
[class^="standardSidebarView_"] {
    background: rgb(var(--jg-tint) / var(--jg-panel-opacity)) !important;
    backdrop-filter: blur(var(--jg-blur));
}

/* Top title bar: lighter tint so the image still shows */
[class^="bar_"] {
    background: rgb(var(--jg-tint) / calc(var(--jg-panel-opacity) * 0.5)) !important;
}

/* Right-click menus: frosted too. (Not dialogs: a blur there breaks the
   layout of full-screen ones like the image viewer.) */
[role="menu"] {
    backdrop-filter: blur(var(--jg-blur));
}

/* ---- Background effects (snow, rain, leaves, stars, fireflies) ----
   Two depth layers per surface: ::before = far (small, faint, slow),
   ::after = near (big, bright, fast). Each layer also sways and pulses on
   its own uneven cycle so the pattern never visibly repeats.
   "panels" (default): drawn over the glass panels but under the text.
   "front": drawn over everything (clicks still go through). */
#app-mount {
    --jg-fx-panel: var(--jg-fx-on, none);
    --jg-fx-front: none;
}

@container style(--jg-effect-layer: front) {
    #app-mount {
        --jg-fx-panel: none;
        --jg-fx-front: var(--jg-fx-on, none);
    }
}

#app-mount::before,
#app-mount::after,
[class^="sidebar_"]::before,
[class^="sidebar_"]::after,
[class^="page_"]::before,
[class^="page_"]::after {
    content: "";
    position: fixed;
    left: -120px;
    top: -120px;
    pointer-events: none;
    background: var(--jg-fx-img) var(--jg-fx-pos, 0 0) / var(--jg-fx-tw) var(--jg-fx-th) repeat;
    opacity: var(--jg-fx-op);
    will-change: transform, translate, opacity;
    animation:
        jg-fx-move calc(var(--jg-fx-dur) / var(--jg-effect-speed) * var(--jg-fx-k)) linear infinite var(--jg-fx-dir, normal),
        jg-fx-sway calc(var(--jg-fx-swt) / var(--jg-effect-speed) * var(--jg-fx-tm)) ease-in-out infinite,
        var(--jg-fx-pulse, jg-fx-none) calc(var(--jg-fx-pt) * var(--jg-fx-tm)) ease-in-out infinite alternate;
    --jg-fx-tw: calc(var(--jg-fx-w) * var(--jg-effect-size));
    --jg-fx-th: calc(var(--jg-fx-h) * var(--jg-effect-size));
    --jg-fx-dx: calc(var(--jg-fx-tw) * var(--jg-fx-nx));
    --jg-fx-dy: calc(var(--jg-fx-th) * var(--jg-fx-ny));
    --jg-fx-op: calc(var(--jg-effect-opacity) * var(--jg-fx-alpha));
}

/* far layer */
#app-mount::before,
[class^="sidebar_"]::before,
[class^="page_"]::before {
    --jg-fx-img: var(--jg-fx-far);
    --jg-fx-k: 1.35;
    --jg-fx-tm: 1;
    --jg-fx-alpha: 0.75;
}

/* near layer */
#app-mount::after,
[class^="sidebar_"]::after,
[class^="page_"]::after {
    --jg-fx-img: var(--jg-fx-near);
    --jg-fx-k: 0.8;
    --jg-fx-tm: 1.43;
    --jg-fx-alpha: 1;
    --jg-fx-pos: 41% 63%;
    animation-delay: -0.4s, -3.1s, -5.3s;
}

/* Front mode: layers cover the whole window, above everything */
#app-mount::before,
#app-mount::after {
    display: var(--jg-fx-front);
    width: calc(100vw + var(--jg-fx-dx) + 240px);
    height: calc(100vh + var(--jg-fx-dy) + 240px);
    z-index: 2147483000;
}

/* Panels mode: layers inside each glass panel, above the panel's tint
   but below its content. (The panel's backdrop-filter makes it the box
   these fixed layers are positioned in.) */
[class^="sidebar_"]::before,
[class^="sidebar_"]::after,
[class^="page_"]::before,
[class^="page_"]::after {
    display: var(--jg-fx-panel);
    width: calc(100% + var(--jg-fx-dx) + 240px);
    height: calc(100% + var(--jg-fx-dy) + 240px);
    z-index: -1;
}

/* shift the right-hand panel so it doesn't mirror the left one */
[class^="page_"]::before {
    --jg-fx-pos: 67% 18%;
    animation-delay: -0.9s, -6.7s, -11.2s;
}

[class^="page_"]::after {
    --jg-fx-pos: 13% 82%;
    animation-delay: -1.3s, -9.4s, -2.6s;
}

@container not style(--jg-effect: none) {
    [class^="sidebar_"],
    [class^="page_"] {
        overflow: clip;
    }
}

@keyframes jg-fx-move {
    from { transform: translate(calc(var(--jg-fx-dx) * -1), calc(var(--jg-fx-dy) * -1)); }
    to   { transform: translate(0, 0); }
}

/* uneven side-to-side drift (wind, swaying, wandering) */
@keyframes jg-fx-sway {
    0%, 100% { translate: 0 0; }
    23% { translate: calc(var(--jg-fx-sx) * var(--jg-effect-size)) calc(var(--jg-fx-sy) * -1 * var(--jg-effect-size)); }
    51% { translate: calc(var(--jg-fx-sx) * -0.35 * var(--jg-effect-size)) calc(var(--jg-fx-sy) * var(--jg-effect-size)); }
    74% { translate: calc(var(--jg-fx-sx) * 0.6 * var(--jg-effect-size)) calc(var(--jg-fx-sy) * 0.4 * var(--jg-effect-size)); }
}

/* rain/snow/leaves get heavier and lighter */
@keyframes jg-fx-intensity {
    0%   { opacity: calc(var(--jg-fx-op) * 0.55); }
    40%  { opacity: var(--jg-fx-op); }
    70%  { opacity: calc(var(--jg-fx-op) * 0.8); }
    100% { opacity: var(--jg-fx-op); }
}

/* stars/fireflies twinkle */
@keyframes jg-fx-twinkle {
    from { opacity: calc(var(--jg-fx-op) * 0.3); }
    to   { opacity: var(--jg-fx-op); }
}

